# $this: in a class, the instance; in a script property or method, the object it's on.
$this = $null
# $PSScriptRoot: the folder of the script or module running.
$PSScriptRoot = ''
# $PSCommandPath: the full path of the script or module running.
$PSCommandPath = ''
# $MyInvocation: about the current command: its name, line, MyCommand.Path (the script's path), BoundParameters.
$MyInvocation = $null
# $PSBoundParameters: the parameters passed to the function or script, by name.
$PSBoundParameters = @{}
# $PSCmdlet: in an advanced function, the cmdlet object (ShouldProcess, WriteError, ParameterSetName).
$PSCmdlet = $null
# $LASTEXITCODE: the exit code of the last native program run.
$LASTEXITCODE = 0
# $Error: the session's errors, the newest first.
$Error = @()
# $Host: the host program's object.
$Host = $null
# $HOME: the user's home folder.
$HOME = ''
# $PID: this PowerShell process's id.
$PID = 0
# $PWD: the current location (a PathInfo).
$PWD = $null
# $PSHOME: PowerShell's install folder.
$PSHOME = ''
# $PSVersionTable: PowerShell's version, edition and platform.
$PSVersionTable = @{}
# $PSEdition: 'Core' (PowerShell 6 and later) or 'Desktop' (Windows PowerShell).
$PSEdition = ''
# $IsWindows: whether PowerShell runs on Windows (PowerShell 6 and later).
$IsWindows = $true
# $IsLinux: whether PowerShell runs on Linux (PowerShell 6 and later).
$IsLinux = $false
# $IsMacOS: whether PowerShell runs on macOS (PowerShell 6 and later).
$IsMacOS = $false
# $IsCoreCLR: whether PowerShell runs on .NET (Core).
$IsCoreCLR = $true
# $ExecutionContext: the engine's intrinsics (InvokeCommand, SessionState).
$ExecutionContext = $null
# $Matches: the groups the last -match matched.
$Matches = @{}
# $Sender: in an event action, the object that raised the event.
$Sender = $null
# $Event: in an event action, the event.
$Event = $null
# $EventArgs: in an event action, its arguments.
$EventArgs = $null
# $StackTrace: the stack trace of the last error.
$StackTrace = ''
# $ShellId: the shell's id.
$ShellId = ''
# $NestedPromptLevel: how deep in nested prompts this is.
$NestedPromptLevel = 0
# $PSCulture: the culture's name.
$PSCulture = ''
# $PSUICulture: the UI culture's name.
$PSUICulture = ''
# $PSSenderInfo: in a remote session, about its user.
$PSSenderInfo = $null
# $ConsoleFileName: the console file last used.
$ConsoleFileName = ''
# $ErrorActionPreference: what a non-terminating error does: Continue (the default), Stop, SilentlyContinue, Inquire, Ignore.
$ErrorActionPreference = 'Continue'
# $WarningPreference: what a warning does.
$WarningPreference = 'Continue'
# $VerbosePreference: whether verbose messages show (SilentlyContinue by default).
$VerbosePreference = 'SilentlyContinue'
# $DebugPreference: whether debug messages show.
$DebugPreference = 'SilentlyContinue'
# $InformationPreference: whether Write-Information messages show.
$InformationPreference = 'SilentlyContinue'
# $ProgressPreference: whether progress bars show.
$ProgressPreference = 'Continue'
# $ConfirmPreference: the impact level that asks for confirmation.
$ConfirmPreference = 'High'
# $WhatIfPreference: whether commands only say what they'd do.
$WhatIfPreference = $false
# $PSDefaultParameterValues: default values for cmdlets' parameters, by 'Cmdlet:Parameter'.
$PSDefaultParameterValues = @{}
# $PSNativeCommandUseErrorActionPreference: whether a native program's non-zero exit is an error.
$PSNativeCommandUseErrorActionPreference = $false
# $PSNativeCommandArgumentPassing: how arguments reach native programs (Standard, Legacy, Windows).
$PSNativeCommandArgumentPassing = 'Standard'
# $OFS: the separator joining an array's items in a string.
$OFS = ' '
# $OutputEncoding: the encoding of text piped to native programs.
$OutputEncoding = $null
# $PSModuleAutoLoadingPreference: whether modules load when their commands are used.
$PSModuleAutoLoadingPreference = 'All'
# $PSStyle: ANSI styles for output.
$PSStyle = $null
# $MaximumHistoryCount: how many commands the history keeps.
$MaximumHistoryCount = 4096

# ---- Environment variables the system sets ($env:NAME)

# $env:PATH: the folders searched for programs (';' on Windows, ':' elsewhere).
$env:PATH = ''
# $env:PATHEXT: on Windows, the extensions of runnable files.
$env:PATHEXT = ''
# $env:PSModulePath: the folders searched for modules.
$env:PSModulePath = ''
# $env:TEMP: on Windows, the user's temporary folder.
$env:TEMP = ''
# $env:TMP: on Windows, the user's temporary folder.
$env:TMP = ''
# $env:TMPDIR: on macOS and Linux, the temporary folder.
$env:TMPDIR = ''
# $env:HOME: on macOS and Linux, the user's home folder.
$env:HOME = ''
# $env:USER: on macOS and Linux, the user's name.
$env:USER = ''
# $env:SHELL: on macOS and Linux, the user's login shell.
$env:SHELL = ''
# $env:USERPROFILE: on Windows, the user's home folder.
$env:USERPROFILE = ''
# $env:USERNAME: on Windows, the user's name.
$env:USERNAME = ''
# $env:USERDOMAIN: on Windows, the user's domain.
$env:USERDOMAIN = ''
# $env:COMPUTERNAME: on Windows, the computer's name.
$env:COMPUTERNAME = ''
# $env:APPDATA: on Windows, the user's roaming app data folder.
$env:APPDATA = ''
# $env:LOCALAPPDATA: on Windows, the user's local app data folder.
$env:LOCALAPPDATA = ''
# $env:ProgramData: on Windows, the folder of app data for every user.
$env:ProgramData = ''
# $env:ProgramFiles: on Windows, the folder of installed programs.
$env:ProgramFiles = ''
# $env:SystemRoot: on Windows, the Windows folder.
$env:SystemRoot = ''
# $env:WINDIR: on Windows, the Windows folder.
$env:WINDIR = ''
# $env:SystemDrive: on Windows, the drive Windows is on.
$env:SystemDrive = ''
# $env:ComSpec: on Windows, cmd.exe's path.
$env:ComSpec = ''
# $env:OS: on Windows, 'Windows_NT'.
$env:OS = ''
# $env:NUMBER_OF_PROCESSORS: on Windows, the number of logical processors.
$env:NUMBER_OF_PROCESSORS = ''
# $env:PROCESSOR_ARCHITECTURE: on Windows, the processor architecture of this process (AMD64, ARM64, x86).
$env:PROCESSOR_ARCHITECTURE = ''
# $env:PROCESSOR_ARCHITEW6432: on Windows, in a 32-bit process on a 64-bit system, the system's architecture.
$env:PROCESSOR_ARCHITEW6432 = ''

